        if z_score > 1.96:  # 95% confidence for hot spots
            hot_cold_spots[borough] = (z_score, 'HOT')
        elif z_score < -1.96:  # 95% confidence for cold spots
            hot_cold_spots[borough] = (z_score, 'COLD')

# Print the results for hot and cold spots
if hot_cold_spots:
    for borough, (z_score, status) in hot_cold_spots.items():
        print(f"{borough} ({status}, Gi*={z_score:.4f})")
else:
